// ui_screen.js

const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

const ui_toolbar = require('ui_toolbar')
const ui_filter_bar = require('ui_filter_bar')
const ui_components = require('ui_components')
const ui_datasets = require('ui_datasets')
const ui_my_saves = require('ui_my_saves') 

module.exports = ui_screen

async function ui_screen (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject
  }

  const { io } = net(id)

  io.on = {
    up: (msg) => {
      console.log('ui_screen:', msg.type)
    },
    toolbar: toolbar_protocol,
    filter_bar: filter_bar_protocol,
    components: components_protocol,
    datasets: datasets_protocol,
    my_saves: my_saves_protocol
  }

  if (invite) io.accept(invite)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="ui-screen-canvas">

      <div class="screen-content"></div>

      <div class="filter-bar-layer"></div>

      <div class="footer">
        <div class="bottom-bar"></div>
      </div>

    </div>
  `

  const sheet = new CSSStyleSheet()
  
  shadow.adoptedStyleSheets = [sheet]

  const content = shadow.querySelector('.screen-content')
  const filter_bar_layer = shadow.querySelector('.filter-bar-layer')
  const bottom_bar = shadow.querySelector('.bottom-bar')

  const subs = await sdb.watch(onbatch)
  const [toolbar_sid, filter_sid, components_sid, dataset_sid, my_saves_sid] = subs

  let showingComponents = true
  let components = null
  let datasets = null
  let my_saves = null

  // -----------------------------------
  // UI Toolbar 
  // -----------------------------------
  const toolbar = await ui_toolbar({ ...toolbar_sid }, io.invite('toolbar', { up: id }))

  bottom_bar.append(toolbar)

  // -----------------------------------
  // UI Filter Bar (Above Footer Layer)
  // -----------------------------------
  const filter_bar = await ui_filter_bar({ ...filter_sid }, io.invite('filter_bar', { up: id }))

  filter_bar_layer.append(filter_bar)

  // -----------------------------------
  // COMPONENTS + DATASETS (PRE-CREATE BOTH)
  // -----------------------------------
  components = await ui_components({ ...components_sid }, io.invite('components', { up: id }))

  datasets = await ui_datasets({ ...dataset_sid }, io.invite('datasets', { up: id }))

  my_saves = await ui_my_saves({ ...my_saves_sid }, io.invite('my_saves', { up: id }))

  content.append(components)

  return el

  function filter_bar_protocol (msg) {
    console.log('[ui_screen] filter_bar ->', msg.type)

    switch (msg.type) {
    case 'show_view':
      if (msg.data.view === 'components') content.replaceChildren(components)
      if (msg.data.view === 'datasets') content.replaceChildren(datasets)
      if (msg.data.view === 'my_saves') content.replaceChildren(my_saves)
      break
    }
  }

  function toolbar_protocol (msg) {
    console.log('[ui_screen] toolbar ->', msg.type)

    switch (msg.type) {
    case 'toggle_components':
      showingComponents = !showingComponents

      content.replaceChildren(
        showingComponents ? components : datasets
      )
      break

    case 'close':
      console.log('[ui_screen] close clicked')
      break
    }
  }

  function my_saves_protocol (msg) {
    console.log('[ui_screen] my_saves ->', msg.type)
  }

  function components_protocol (msg) {
    console.log('[ui_screen] components ->', msg.type)
  }

  function datasets_protocol (msg) {
    console.log('[ui_screen] datasets ->', msg.type)
  }

  // -----------------------------------
  // BATCH HANDLER
  // -----------------------------------
  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(load_path_raw)
      )

      const handler = on[type] || fail
      handler({ data, type })
    }

    function load_path_raw (path) {
      return drive.get(path).then(read_drive_file_raw)
    }

    function read_drive_file_raw (file) {
      return file.raw
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }

  function fail ({ type, data }) {
    console.warn('ui_screen: unknown batch type', type, data)
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: {
      ui_toolbar: { $: '' },
      ui_filter_bar: { $: '' },
      ui_components: { $: '' },
      ui_datasets: { $: '' },
      ui_my_saves: { $: '' },
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        ui_toolbar: {
          0: '', 
          mapping: { style: 'style', icons: 'icons' }
        },
        ui_filter_bar: {
          0: '', 
          mapping: { style: 'style', icons: 'icons' }
        },
        ui_components: {
          0: '',
          mapping: { style: 'style' }
        },
        ui_datasets: {
          0: '',
          mapping: { style: 'style' }
        },
        ui_my_saves: {
          0: '',
          mapping: { style: 'style', icons: 'icons' }
        },
        net_helper: {
          0: ''
        }
      },

      drive: {
        'style/ui_screen.css': {
          $ref: 'ui_screen.css'
        }
      }
    }
  }
}
